#!/bin/bash
# build-freebian.sh - builds freebian-amd64.iso from the project generated by init-freebian.sh.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_DIR="${FREEBIAN_PROJECT_DIR:-${SCRIPT_DIR}/freebian-build}"
OUTPUT_ISO="${SCRIPT_DIR}/freebian-amd64.iso"
DEBIAN_MIRROR="${FREEBIAN_MIRROR:-http://deb.debian.org/debian/}"

log() { printf '[build-freebian] %s\n' "$*"; }
die() { printf '[build-freebian] ERROR: %s\n' "$*" >&2; exit 1; }

# lb needs root (debootstrap, chroot, mounts)
if [ "${EUID}" -ne 0 ]; then
    command -v sudo >/dev/null 2>&1 || die "run as root or install sudo"
    exec sudo -E FREEBIAN_PROJECT_DIR="${PROJECT_DIR}" "$0" "$@"
fi

command -v apt-get >/dev/null 2>&1 || die "this script needs a Debian or Ubuntu host (apt-get not found)"

# ---------------------------------------------------------------------------
# Host packages
# ---------------------------------------------------------------------------
HOST_PACKAGES=(
    live-build debootstrap squashfs-tools xorriso
    grub-pc-bin grub-efi-amd64-bin grub-common mtools dosfstools
    syslinux syslinux-common isolinux
    curl gnupg ca-certificates debian-archive-keyring
    zstd python3 ovmf
)

MISSING=()
for pkg in "${HOST_PACKAGES[@]}"; do
    if ! dpkg -s "${pkg}" >/dev/null 2>&1; then
        MISSING+=("${pkg}")
    fi
done
if [ "${#MISSING[@]}" -gt 0 ]; then
    log "Installing missing host packages: ${MISSING[*]}"
    export DEBIAN_FRONTEND=noninteractive
    apt-get update
    apt-get install -y --no-install-recommends "${MISSING[@]}"
else
    log "All host packages are present"
fi

# Older host debootstrap releases do not know 'forky'; sid's script is identical in structure.
if [ ! -e /usr/share/debootstrap/scripts/forky ]; then
    log "debootstrap has no 'forky' script; linking it to 'sid'"
    ln -s sid /usr/share/debootstrap/scripts/forky
fi

# ---------------------------------------------------------------------------
# Project
# ---------------------------------------------------------------------------
if [ ! -d "${PROJECT_DIR}/config/hooks/live" ]; then
    log "Project not found; running init-freebian.sh"
    [ -x "${SCRIPT_DIR}/init-freebian.sh" ] || die "init-freebian.sh not found next to this script"
    FREEBIAN_PROJECT_DIR="${PROJECT_DIR}" "${SCRIPT_DIR}/init-freebian.sh"
fi

cd "${PROJECT_DIR}"

log "Cleaning previous build state"
lb clean --purge >/dev/null 2>&1 || lb clean

# SquashFS: zstd level 19, 1 MiB blocks
export MKSQUASHFS_OPTIONS="-comp zstd -Xcompression-level 19 -b 1M"

log "Configuring live-build"
lb config \
    --mode debian \
    --distribution forky \
    --architectures amd64 \
    --linux-flavours amd64 \
    --archive-areas "main contrib non-free non-free-firmware" \
    --parent-archive-areas "main contrib non-free non-free-firmware" \
    --mirror-bootstrap "${DEBIAN_MIRROR}" \
    --mirror-chroot "${DEBIAN_MIRROR}" \
    --mirror-binary "${DEBIAN_MIRROR}" \
    --mirror-chroot-security none \
    --mirror-binary-security none \
    --security false \
    --updates false \
    --backports false \
    --debootstrap-options "--variant=minbase --include=ca-certificates" \
    --apt-recommends false \
    --apt-indices false \
    --firmware-chroot true \
    --system live \
    --binary-images iso-hybrid \
    --bootloaders "syslinux,grub-efi" \
    --debian-installer none \
    --memtest none \
    --win32-loader false \
    --chroot-filesystem squashfs \
    --chroot-squashfs-compression-type zstd \
    --chroot-squashfs-compression-level 19 \
    --iso-application "FreeBian" \
    --iso-publisher "FreeBian Project" \
    --iso-volume "FREEBIAN" \
    --image-name "freebian" \
    --bootappend-live "boot=live components quiet splash username=freebian hostname=freebian locales=en_US.UTF-8 keyboard-layouts=us" \
    --bootappend-live-failsafe "boot=live components memtest noapic noapm nodma nomce nosmp nosplash vga=788" \
    --cache true \
    --cache-packages true \
    --cache-indices false \
    --verbose

log "Building (output is written to ${PROJECT_DIR}/build.log)"
lb build 2>&1 | tee build.log

# ---------------------------------------------------------------------------
# Artifact
# ---------------------------------------------------------------------------
shopt -s nullglob
ISO_CANDIDATES=( ./*.iso )
shopt -u nullglob
[ "${#ISO_CANDIDATES[@]}" -gt 0 ] || die "lb build finished but produced no .iso; see ${PROJECT_DIR}/build.log"

mv -f "${ISO_CANDIDATES[0]}" "${OUTPUT_ISO}"
log "ISO: ${OUTPUT_ISO}"

# Checksum
( cd "${SCRIPT_DIR}" && sha256sum "freebian-amd64.iso" > "freebian-amd64.iso.sha256" )
( cd "${SCRIPT_DIR}" && sha256sum -c "freebian-amd64.iso.sha256" )

# Boot structure: must have both BIOS (El Torito) and UEFI entries
ELTORITO="$(xorriso -indev "${OUTPUT_ISO}" -report_el_torito plain 2>/dev/null || true)"
printf '%s\n' "${ELTORITO}" | grep -qi 'BIOS' || log "WARNING: no BIOS El Torito entry reported"
printf '%s\n' "${ELTORITO}" | grep -qi 'UEFI' || log "WARNING: no UEFI El Torito entry reported"

# SquashFS parameters actually used
SQUASH="${PROJECT_DIR}/binary/live/filesystem.squashfs"
if [ -f "${SQUASH}" ] && command -v unsquashfs >/dev/null 2>&1; then
    SQINFO="$(unsquashfs -s "${SQUASH}" 2>/dev/null || true)"
    printf '%s\n' "${SQINFO}" | grep -Ei 'Compression|Block size' || true
    printf '%s\n' "${SQINFO}" | grep -qi 'zstd' || log "WARNING: filesystem.squashfs is not zstd compressed"
    printf '%s\n' "${SQINFO}" | grep -q 'Block size 1048576' || log "WARNING: squashfs block size is not 1 MiB; this live-build version ignored MKSQUASHFS_OPTIONS"
fi

log "SHA256: $(cut -d' ' -f1 "${SCRIPT_DIR}/freebian-amd64.iso.sha256")"
log "Size:   $(du -h "${OUTPUT_ISO}" | cut -f1)"
log "Done."
